    first=_compare(g,c.named(g,'st_path_chain_order','INT'),0)
    declared=c._stat(g,paths,owner*first,'Sum')
    registry=c.V(g,source_ok)*_compare(g,count,declared)
    registry=registry*_compare(g,count,0,'GREATER_THAN')*_compare(g,count,128,'LESS_EQUAL')
    permitted=c.named(g,'st_path_divided','BOOLEAN')
