    permitted=permitted*(1.-c.named(g,'st_path_attached_end','BOOLEAN'))
    permitted=permitted*_compare(g,c.named(g,'st_path_bundle_id','INT'),0,'GREATER_EQUAL')
    registry=registry*c._stat(g,paths,permitted)*g.math('GREATER_THAN',c._count(g,paths),1.5)
