def guard_saved(original):
    """Add the original seam/allocation checks to a saved Bundle branch.

    This copies only the small entry wrapper. The saved shared surface kernel
    and its corner/profile construction are retained without reconstruction.
    """
    if not original.get('blosm_free_bundle_surfaces') or original.get('blosm_free_bundle_guards',0)>=3:
        raise ValueError('Require an unguarded free Bundle input branch')
    tree=original.copy();tree.name=original.name+' / Bundle input guards'
    if original.get('blosm_free_bundle_guards'):
        return _diagnostic_units(tree)
    g=object.__new__(c.Graph);g.g=tree;g.count=len(tree.nodes);g.frame=None
    inp=next(n for n in tree.nodes if n.type=='GROUP_INPUT')
    out=next(n for n in tree.nodes if n.type=='GROUP_OUTPUT' and n.is_active_output)
    kernel=next(n for n in tree.nodes if n.label=='Shared complete Bundle union and separator construction')
    paths=next(n for n in tree.nodes if n.label=='Declared complete Bundle path bindings').outputs['Geometry']
    gate=kernel.inputs['Paths'].links[0].from_node
    registry=gate.inputs['Switch'].links[0].from_socket
    consumers=[link.to_socket for link in registry.links]
    checked=c.V(g,registry)
    # Missing metadata must never turn into default-zero indices and create an
    # apparently valid, differently owned Bundle. Geometry checks stay in GN.
    required={
        'INT':('id','start','count','edge','partner','bundle_id','chain_index','chain_order',
               'chain_partner','start_seam','end_seam'),
        'BOOLEAN':('divided','attached_start','attached_end','partner_reversed','make_grass',
                   'chain_forward','chain_aggregate','chain_reversed','chain_owner'),
        'FLOAT':('rise','datum','clip_start','clip_end','inner_u','chain_inner_u')}
    for kind,names in required.items():
        for name in names:
            attr=g.node('GeometryNodeInputNamedAttribute','Required Bundle binding / '+name)
            attr.data_type=kind;attr.inputs['Name'].default_value='st_path_'+name
            checked=checked*c._stat(g,paths,attr.outputs['Exists'])
    checked=checked*_compare(g,c._count(g,paths),4096,'LESS_EQUAL')
    radial=kernel.inputs['Radial Samples'].links[0].from_socket
    checked=checked*_compare(g,radial,256,'LESS_EQUAL')
    for socket in consumers:g.bind(checked,socket)
    seam=g.node('GeometryNodeGroup','Bundle member Section seam compatibility')
    seam.node_tree=unified_seam_nodes.build(local_diagnostics=True)
    g.bind(kernel.inputs['Sources'].links[0].from_socket,seam.inputs['Sources'])
    g.bind(gate.outputs['Output'],seam.inputs['Paths'])
    g.bind(seam.outputs['Paths'],kernel.inputs['Paths'])
    # The legacy Bundle kernel emits point-cloud diagnostics, whereas the
    # original-span interface transports mesh vertices. Keep both rejection
    # representations; Mesh to Points alone would silently discard the former.
    display=next(n for n in tree.nodes if n.label=='Native Bundle rejection records')
    failures=display.inputs['Mesh'].links[0].from_socket
    consumers=list(failures.links)
    components=g.node('GeometryNodeSeparateComponents','Preserve both native diagnostic representations')
    g.bind(failures,components.inputs['Geometry'])
    vertices=g.node('GeometryNodePointsToVertices','Bundle diagnostics as original-span records')
    g.bind(components.outputs['Point Cloud'],vertices.inputs['Points'])
    normalized=boundary._join(g,components.outputs['Mesh'],vertices.outputs['Mesh'])
    normalized=g.store(normalized,'st_cn_kind',8,'POINT','INT')
    normalized=g.store(normalized,'st_cn_owner',c.named(g,'st_bundle_id','INT'),'POINT','INT')
    for link in consumers:
        socket=link.to_socket;tree.links.remove(link);g.bind(normalized,socket)
    # The original status describes the merged original-span source view. An
    # independent Bundle-only input has no such view. Publish its own precise
    # status instead of reporting a missing, unused view as a source failure.
    g.socket('Bundle Input Status','NodeSocketGeometry','OUTPUT')
    active=_compare(g,inp.outputs['Bundle Count'],0,'GREATER_THAN')
    status=c._line(g,1)
    for name,value in (('bundle_registry_valid',checked),('bundle_seams_valid',seam.outputs['Valid']),
                       ('bundle_surface_valid',kernel.outputs['Valid'])):
        status=c._store(g,status,name,value,'BOOLEAN')
    g.bind(boundary._empty(g,status,active),out.inputs['Bundle Input Status'])
    old_count=c.V(g,inp.outputs['Standalone Count'])+c.V(g,inp.outputs['Boundary Run Count'])
    sites=next(n for n in tree.nodes if n.label=='Existing original junction ownership').outputs['Geometry']
    has_old=g.math('GREATER_THAN',old_count+c._count(g,sites),0.)
