def _diagnostic_units(tree):
    """Geometry uses Blender units; Failure Records retain metric coordinates."""
    g=object.__new__(c.Graph);g.g=tree;g.count=len(tree.nodes);g.frame=None
    inp=next(n for n in tree.nodes if n.type=='GROUP_INPUT')
    display=next(n for n in tree.nodes if n.label=='Native Bundle rejection records')
    components=next(n for n in tree.nodes if n.label=='Preserve both native diagnostic representations')
    raw=components.inputs['Geometry'].links[0].from_socket
    normalized=display.inputs['Mesh'].links[0].from_socket
    # Upgrade older wrappers which appended to a Join Geometry multi-input
    # without removing its original link. Keep exactly one normalized stream.
    for link in list(raw.links):
        if link.to_node==components:continue
        socket=link.to_socket;tree.links.remove(link)
        if not any(l.to_socket==socket for l in normalized.links):g.bind(normalized,socket)
    transform=next((n for n in tree.nodes if n.label=='Bundle diagnostic positions in Blender units'),None)
    if transform is None:
        transform=g.node('GeometryNodeTransform','Bundle diagnostic positions in Blender units')
        g.bind(display.outputs['Points'],transform.inputs['Geometry'])
    g.bind(inp.outputs['Metres to Blender Units'],transform.inputs['Scale'])
    for link in list(display.outputs['Points'].links):
        if link.to_node==transform:continue
        socket=link.to_socket;tree.links.remove(link)
        if not any(l.to_socket==socket for l in transform.outputs['Geometry'].links):
            g.bind(transform.outputs['Geometry'],socket)
    tree['blosm_free_bundle_guards']=3
    return tree
